cd /home/runner/work/beetle-in-the-anthill/beetle-in-the-anthill && python3 - <<'EOF'
import subprocess,re,glob
def git(*a): return subprocess.run(["git"]+list(a),capture_output=True,text=True).stdout
recorded={}
for f in glob.glob("S0*/E*.md"):
    txt=open(f).read()
    for m in re.finditer(r"Source: friend/(\w+) @ ([0-9a-f]{40})", txt):
        recorded[m.group(2)]=(f,m.group(1))
branches=["rachel","monica","phoebe","joey","chandler","ross"]
allsha=set()
for b in branches:
    out=git("log","--format=%H",f"origin/friend/{b}")
    allsha.update(out.split())
for s,(f,br) in recorded.items():
    if s not in allsha:
        print("recorded but not on branch:",s,f,br)
EOF
